def calculate_S(x, y, z, a, b, c):
    return abs(x+y-a-b) + abs(y+z-b-c) + abs(z+x-c-a)

# Test with the simple query (0, 0, 0)
a, b, c = 0, 0, 0

def S_simple(x, y, z):
    return calculate_S(x, y, z, a, b, c)

# Fix x=1, y=2, vary z
x_fixed = 1
y_fixed = 2
z_values = range(10)
results = {}
for z in z_values:
    S = S_simple(x_fixed, y_fixed, z)
    results[z] = S

print(f"Fixed x={x_fixed}, y={y_fixed}. S values as z varies:")
for z, S in results.items():
    print(f"z={z}, S={S}")
